<?php declare(strict_types=1);
require __DIR__.'/donation-forms.php';
use Kulturhus\Verein\{DonationReceipts,SettingsSchema};
$start=$checks;
$receipts=new DonationReceipts($db,'writer');
$fresh=$forms->defaults('money',$entry)+['receipt_reviewed'=>'1'];
denied(fn()=>$receipts->issue($fresh,$key()),'incomplete tax settings cannot issue');
$tax=array_replace(SettingsSchema::defaults('tax'),['office'=>'Musterstadt','number'=>'00/000/00000','purpose'=>'Förderung von Kunst und Kultur','notice_type'=>'exemption','exemption_date'=>'2025-02-01','assessment'=>'2022 bis 2024','membership_deductible'=>'no']);
$noticeId=$docs->upload('synthetic-notice.pdf',$pdf,['title'=>'Synthetic tax notice','kind'=>'other','scope'=>'finance','document_date'=>'2025-02-01','links'=>[]],$key());$tax['notice_document_id']=$noticeId;$tax['receipt_signatory']='Test Authority';$tax['receipt_authority_reviewed']=true;
$financeSettings=new \Kulturhus\Verein\Settings($db,'writer');$financeSettings->save('tax',$tax,0);
$fresh=$forms->defaults('money',$entry)+['receipt_reviewed'=>'1'];
denied(fn()=>(new DonationReceipts($db,'reader'))->issue($fresh,$key()),'reader cannot issue');
denied(fn()=>$receipts->issue(array_replace($fresh,['receipt_reviewed'=>'']),$key()),'explicit substantive review required');
denied(fn()=>$receipts->issue(array_replace($fresh,['donor'=>'Only name']),$key()),'donor address required');
denied(fn()=>$receipts->issue(array_replace($fresh,['tax_number'=>'different']),$key()),'cannot override saved tax authority details');
denied(fn()=>$receipts->issue(array_replace($fresh,['amount'=>'900']),$key()),'cannot certify invented payment amount');
$fresh['waiver']='no';$token=$key();$issued=$receipts->issue($fresh,$token);$file=$docs->file($issued);$snap=json_decode($file['snapshot'],true);
check($snap['kind']==='donation_receipt'&&$snap['signature_mode']==='handwritten'&&$snap['non_deductible_memberships']===true,'issued snapshot explicitly paper signature and non-deductible membership clause');
check(str_starts_with($snap['receipt_number'],'ZB-')&&$docs->document($issued)['kind']==='certificate','numbered certificate archived');
check($receipts->issue($fresh,$token)===$issued,'retry returns exact original');
denied(fn()=>$receipts->issue(array_replace($fresh,['donor'=>"Other\nStreet 2\n00000 City"]),$token),'retry cannot change donor');
denied(fn()=>$receipts->issue($fresh,$key()),'second form cannot certify same payment');
check(!$docs->canEdit($issued),'issued certificate metadata immutable');
$allocation=$finance->allocations($entry)[0];$transaction=$finance->transactionDetail($allocation['transaction_id']);
denied(fn()=>$finance->releaseAllocation($allocation['id'],$transaction['version'],3,'Correction'),'certified allocation cannot be removed');
denied(fn()=>$finance->reverse($entry,3,'2026-09-06','Correction'),'certified payment cannot be reversed');
denied(fn()=>(new DonationReceipts($db,'foreign'))->cancel($snap['receipt_number'],'Foreign cancellation'),'other club cannot cancel');
denied(fn()=>$receipts->cancel($snap['receipt_number'],''),'cancellation reason required');
$receipts->cancel($snap['receipt_number'],'Synthetic correction; no actual recipient');
check($docs->document($issued)['state']==='archived'&&$docs->file($issued)['sha256']===$file['sha256'],'cancellation preserves original bytes and archives it');
check((int)$db->query('SELECT COUNT(*) FROM donation_receipt_claims')->fetchColumn()===0,'cancel releases certificate claims');
denied(fn()=>$receipts->cancel($snap['receipt_number'],'Again'),'repeat cancellation denied');
$replacement=$receipts->issue($fresh,$key());check($replacement!==$issued,'replacement after cancellation has own immutable certificate');
check(count($receipts->listing('money',$entry))===2,'both original and replacement visible');
$unpaid=$finance->createEntry($moneyData,$key());$unpaidForm=$forms->defaults('money',$unpaid)+['receipt_reviewed'=>'1'];
denied(fn()=>$receipts->issue($unpaidForm,$key()),'unpaid promise cannot be certified');
$goodsForm=$forms->defaults('goods',$goods)+['receipt_reviewed'=>'1'];$goodsForm['donor']="Robin Muster\nTestweg 3\n00000 Musterort";
denied(fn()=>$receipts->issue(array_replace($goodsForm,['amount'=>'99,00']),$key()),'goods value bound to source');
denied(fn()=>$receipts->issue(array_replace($goodsForm,['donated_on'=>'2026-08-01']),$key()),'goods date bound to source');
$goodsCertificate=$receipts->issue($goodsForm,$key());check($docs->document($goodsCertificate)['kind']==='certificate','goods certificate actually generated');
denied(fn()=>$receipts->issue($goodsForm,$key()),'same goods cannot be certified twice');
$tax['exemption_date']='2019-01-01';$financeSettings->save('tax',$tax,1);
denied(fn()=>$receipts->build(array_replace($forms->defaults('money',$entry),['waiver'=>'no','receipt_reviewed'=>'1'])),'expired exemption denied');
$tax['exemption_date']='2025-02-01';$financeSettings->save('tax',$tax,2);
$dues=$finance->createEntry(array_replace($moneyData,['kind'=>'contribution','category'=>'membership']),$key());$finance->recordPayment($dues,1,$paidAccount,'2026-08-01');
denied(fn()=>$receipts->issue(array_replace($forms->defaults('money',$dues),['waiver'=>'no','receipt_reviewed'=>'1']),$key()),'non-deductible dues cannot receive tax certificate');
// One bank movement can have several partial associations with the same donation.
// Certify the second ordered association: reversal must inspect more than the first.
$splitEntry=$finance->createEntry(array_replace($moneyData,['amount'=>'10,00']),$key());
$splitTx=$finance->createTransaction(['account'=>$paidAccount,'booked_on'=>'2026-08-01','direction'=>'income','amount'=>'10,00','counterparty'=>'Synthetic transfer','description'=>'Unreferenced synthetic payment'],$key());
$finance->allocate($splitTx,1,$splitEntry,1,'4,00',$key());
$finance->allocate($splitTx,2,$splitEntry,2,'6,00',$key());
$splitAllocations=$finance->allocations($splitEntry);
$splitInput=array_replace($forms->defaults('money',$splitEntry,$splitAllocations[1]['id']),['waiver'=>'no','receipt_reviewed'=>'1']);
$claimRead=new PDO(\Kulturhus\Verein\Tests\MySqlFixture::dsn($db),'root','isolated-regression-only',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$claimRead->beginTransaction();$claimRead->query('SELECT COUNT(*) FROM donation_receipt_claims')->fetchColumn();
$splitCertificate=$receipts->issue($splitInput,$key());
try{denied(fn()=>DonationReceipts::assertPaymentMutable($claimRead,'a',$splitAllocations[1]['id']),'older correction snapshot observes the independently committed current donation certificate claim');}finally{$claimRead->rollBack();}
check($finance->canReverseEntry($splitEntry),'same-transaction partial associations structurally allow a joint reversal');
$beforeSplit=$db->query('SELECT COUNT(*) FROM finance_transactions')->fetchColumn();
denied(fn()=>$finance->reverse($splitEntry,3,'2026-08-02','Synthetic correction'),'certificate on non-first partial association blocks entire payment reversal');
check($finance->entry($splitEntry)['payment_state']==='paid'&&$db->query('SELECT COUNT(*) FROM finance_transactions')->fetchColumn()===$beforeSplit,'blocked reversal leaves payment and bank movement unchanged');
$splitSnapshot=json_decode($docs->file($splitCertificate)['snapshot'],true);
$receipts->cancel($splitSnapshot['receipt_number'],'Synthetic cancellation before payment correction');
$finance->reverse($splitEntry,3,'2026-08-02','Synthetic correction after certificate cancellation');
check($finance->entry($splitEntry)['payment_state']==='reversed','joint reversal succeeds after all certificate claims are cancelled');
check(\Kulturhus\Verein\Tests\MySqlFixture::integrity($db)==='ok'&&\Kulturhus\Verein\Tests\MySqlFixture::foreignKeyErrors($db)===[],'receipt registry foreign keys and database intact');
echo ($checks-$start)." receipt checks passed\n";

if($qa=getenv('DONATION_QA_DIR')){if(!is_dir($qa))mkdir($qa,0700,true);file_put_contents($qa.'/money.pdf',$docs->file($replacement)['bytes']);file_put_contents($qa.'/goods.pdf',$docs->file($goodsCertificate)['bytes']);}
